'use strict';
const planningLayer=L.layerGroup().addTo(map);
const checkFields=[['roadAccess','All-season tanker access'],['turning','Turning / staging space'],['connection','Tanker drafting connection'],['refillAccess','Refill access / availability'],['land','Landowner permission / tenure'],['ground','Ground, frost / flood conditions'],['maintenance','Inspection / maintenance responsibility']];
$('accesschecks').innerHTML=checkFields.map(([id,label])=>`<label>${label}<select id="check-${id}"><option>Unknown</option><option>Needs assessment</option><option>Reported suitable</option><option>Constraint identified</option></select></label>`).join('');
function closestWater(coord,type){let match=null,km=Infinity;for(const w of state.water.filter(w=>!w.demo&&w.coord&&w.type===type)){let d=distance(coord,w.coord);if(d<km){match=w;km=d}}return{match,km}}
function gapText(coord){const e=closestWater(coord,'existing'),d=closestWater(coord,'draft');return `${e.match?e.km.toFixed(1)+' km to existing hydrant':'Existing-source distance unavailable'}${d.match?' · '+d.km.toFixed(1)+' km to nearest drafting point':''}`}
function planningIcon(kind){return L.divIcon({className:'',html:`<div class="marker ${kind==='cluster'?'clustermarker':'candidatemarker'}">${kind==='cluster'?'H':'◇'}</div>`,iconSize:[28,28],iconAnchor:[14,14]})}
function qualifying(c){return c.homes!=null&&c.homes>=Math.max(1,Number($('minhomes').value)||1)&&closestWater(c.coord,'existing').km>=Math.max(.1,Number($('gapkm').value)||.1)&&Number.isFinite(closestWater(c.coord,'existing').km)}
function drawPlanning(){planningLayer.clearLayers();$('clusterlist').innerHTML='';$('candidatelist').innerHTML='';$('clustercount').textContent=state.clusters.length+' entered';$('candidatecount').textContent=state.candidates.length+' proposed';
for(const c of state.clusters){if(activeTab==='storage')L.marker(c.coord,{icon:planningIcon('cluster'),title:c.name,alt:c.name}).addTo(planningLayer).bindTooltip(esc(c.name)+' · home cluster').on('click',()=>planEdit('cluster',c));let el=document.createElement('div');el.className='planning-card';let yes=qualifying(c);el.innerHTML=`<button class="item"><span class="badge">${yes?'SCREENING MATCH':'CLUSTER'}</span><strong>${esc(c.name)}</strong><small>${c.homes??'Unknown'} homes · ${esc(c.township||'Township unassigned')}<br>${esc(gapText(c.coord))}<br>${esc(c.countbasis||'Count basis not recorded')}</small></button>${yes?'<p class="hint">Meets your example home-count and distance thresholds. Area merits review; access and installation suitability are unknown.</p><button class="wide suggest">Create candidate area for review</button>':''}`;el.querySelector('.item').onclick=()=>planEdit('cluster',c);if(yes)el.querySelector('.suggest').onclick=()=>planEdit('candidate',null,c.coord,{name:c.name+' — storage study area',cluster:c.id,township:c.township,notes:'Area-level candidate centred on a user-entered home cluster. Exact installation location must be selected after site assessment.'});$('clusterlist').appendChild(el)}
for(const c of state.candidates){L.marker(c.coord,{icon:planningIcon('candidate'),title:c.name+' — proposed, not operational',alt:c.name+' — proposed storage'}).addTo(planningLayer).bindTooltip(esc(c.name)+' · proposed storage').on('click',()=>planEdit('candidate',c));let b=document.createElement('button');b.className='item';let cluster=state.clusters.find(x=>x.id===c.cluster),constraints=checkFields.filter(([k])=>c.checks?.[k]==='Constraint identified').length;b.innerHTML=`<span class="badge purple">PROPOSED</span><strong>${esc(c.name)}</strong><small>${esc(c.capacity??2000)} ${c.unit==='imperial'?'Imperial':c.unit==='us'?'US':'unspecified'} gal · ${esc(c.township||'Township unassigned')}<br>${esc(gapText(c.coord))}<br>${cluster?esc(cluster.name)+' · '+(cluster.homes??'Unknown')+' homes':'No home cluster linked'}<br>${constraints?constraints+' constraints recorded':'Site assessment pending'} · not operational</small>`;b.onclick=()=>planEdit('candidate',c);$('candidatelist').appendChild(b)}
if(!state.clusters.length)$('clusterlist').innerHTML='<p class="hint empty">No home clusters entered. Mark areas you know and record a home count or estimate. No homes have been inferred.</p>';
if(!state.candidates.length)$('candidatelist').innerHTML='<p class="hint empty">No candidate areas yet. Mark a location or use a qualifying home cluster to start a proposal.</p>';
}
function planEdit(kind,r,coord,seed={}){r=r||seed;const cluster=kind==='cluster';$('planform').reset();$('planid').value=r.id||'';$('plankind').value=kind;$('plantitle').textContent=cluster?'Home cluster':'Proposed underground storage';$('planname').value=r.name||'';$('township').value=r.township||'';const p=coord||r.coord;$('planlat').value=p[0].toFixed(6);$('planlng').value=p[1].toFixed(6);$('clusterfields').hidden=!cluster;$('candidatefields').hidden=cluster;$('homes').value=r.homes??'';$('countbasis').value=r.countbasis||'';$('capacity').value=r.capacity??2000;$('gallonunit').value=r.unit||'unspecified';$('linkedcluster').innerHTML='<option value="">None selected</option>'+state.clusters.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('linkedcluster').value=r.cluster||'';for(const [k] of checkFields)$('check-'+k).value=r.checks?.[k]||'Unknown';$('refill').value=r.refill||'';$('benefit').value=r.benefit||'';$('plannotes').value=r.notes||'';$('plandelete').hidden=!r.id;litres();$('planning').showModal()}
function litres(){let n=Number($('capacity').value),u=$('gallonunit').value;$('litres').textContent=u==='unspecified'?'Gallon type is not yet specified. Capacity is a planning assumption, not a confirmed usable firefighting volume.':`Nominal volume ≈ ${Math.round(n*(u==='imperial'?4.54609:3.785411784)).toLocaleString()} litres. Usable capacity and suitability need assessment.`}
$('capacity').oninput=litres;$('gallonunit').onchange=litres;
$('addcluster').onclick=()=>startMode('plan-cluster','Click the centre of a known home cluster. You will enter the count and its basis.');$('addcandidate').onclick=()=>startMode('plan-candidate','Click an area to investigate for underground storage. This does not designate an operational source.');
map.on('click',e=>{if(mode==='plan-cluster'||mode==='plan-candidate')planEdit(mode==='plan-cluster'?'cluster':'candidate',null,[e.latlng.lat,e.latlng.lng])});
$('plancancel').onclick=()=>{$('planning').close();cancelMode()};$('planning').addEventListener('cancel',cancelMode);
$('planform').onsubmit=e=>{e.preventDefault();let kind=$('plankind').value,arr=kind==='cluster'?state.clusters:state.candidates,id=$('planid').value||newRecordId(),old=arr.find(c=>c.id===id),c={...old,id,name:$('planname').value.trim(),coord:[Number($('planlat').value),Number($('planlng').value)],township:$('township').value.trim(),notes:$('plannotes').value};if(!c.name)return;if(kind==='cluster')Object.assign(c,{homes:$('homes').value===''?null:Number($('homes').value),countbasis:$('countbasis').value});else Object.assign(c,{capacity:$('capacity').value===''?null:Number($('capacity').value),unit:$('gallonunit').value,cluster:$('linkedcluster').value,checks:Object.fromEntries(checkFields.map(([k])=>[k,$('check-'+k).value])),refill:$('refill').value,benefit:$('benefit').value,operational:false});let i=arr.findIndex(x=>x.id===id);if(i<0)arr.push(c);else arr[i]=c;save();$('planning').close();cancelMode();drawPlanning()};
$('plandelete').onclick=()=>{if(confirm('Delete this planning record?')){let kind=$('plankind').value,key=kind==='cluster'?'clusters':'candidates',id=$('planid').value;state[key]=state[key].filter(c=>c.id!==id);if(kind==='cluster')for(const c of state.candidates)if(c.cluster===id)c.cluster='';save();$('planning').close();drawPlanning()}};
for(const id of ['minhomes','gapkm'])$(id).oninput=drawPlanning;
const originalRender=render;render=function(){originalRender();drawPlanning()};
for(const b of document.querySelectorAll('nav button')){const previous=b.onclick;b.onclick=()=>{previous();drawPlanning()}}
// Initial study extent is selected by study.js after outline layers load.
drawPlanning();
